// 21mine launch catalogue. Prices are AED (VAT-inclusive display). Stock = opening stock.
// Images are original illustrations generated by scripts/gen-images.ts (replace with photography in Admin > Products).
export type Art =
  | { type: "perfume"; shape: "square" | "round" | "tall" | "facet" | "mini" | "set" | "mist"; liquid: string; cap: string; bg: string }
  | { type: "nails"; shape: "almond" | "square" | "coffin" | "oval" | "stiletto" | "squoval"; color: string; tip?: string; finish: "gloss" | "chrome" | "glitter" | "velvet" | "pearl" | "french"; bg: string }
  | { type: "tool"; tool: "glue" | "tabs" | "oil" | "kit" | "file"; color: string; bg: string }
  | { type: "jewel"; jewel: "huggie" | "necklace" | "bracelet" | "claw" | "scrunchie" | "scarf" | "sunglasses" | "charm"; color: string; accent: string; bg: string };

export type SeedVariant = { sku: string; name: string; options: Record<string, string>; price: number; compareAt?: number; stock: number };
export type SeedProduct = {
  slug: string; name: string; nameAr?: string; category: string;
  kind: "PERFUME" | "PRESS_ON_NAILS" | "NAIL_ACCESSORY" | "FASHION_ACCESSORY";
  short: string; description: string; details: Record<string, string>; highlights: string[]; care?: string;
  featured?: boolean; variants: SeedVariant[]; art: Art;
};

