const PERFUME_CARE = "For external use only. Flammable - keep away from heat and open flame. Store below 30°C away from direct sunlight. Avoid contact with eyes; discontinue use if irritation occurs. Keep out of reach of children.";
const NAIL_CARE = "Do not use on damaged, infected or irritated nails. Nail glue contains cyanoacrylate: bonds skin in seconds, avoid contact with eyes and skin, keep out of reach of children. Remove by soaking in warm soapy water or acetone-free remover - never pull nails off.";
const PRESS_ON_DETAILS = (shape: string, length: string, finish: string) => ({
  Shape: shape, Length: length, Finish: finish,
  "Pieces": "24 nails in 12 sizes (0-11)",
  "In the box": "24 nails, 2 g nail glue, 24 adhesive tabs, mini file, cuticle stick, alcohol pad",
  "Wear time": "Up to 2 weeks with glue, 1-3 days with adhesive tabs",
  Reusable: "Yes, when applied with adhesive tabs and removed gently",
  Material: "ABS, hand-finished gel coat",
});
const nailSizes = (prefix: string, price: number, stocks: [number, number, number, number]) => ([
  { sku: `${prefix}-XS`, name: "XS - Petite", options: { Size: "XS (petite nail beds)" }, price, stock: stocks[0] },
  { sku: `${prefix}-S`, name: "S - Small", options: { Size: "S" }, price, stock: stocks[1] },
  { sku: `${prefix}-M`, name: "M - Medium", options: { Size: "M" }, price, stock: stocks[2] },
  { sku: `${prefix}-L`, name: "L - Large", options: { Size: "L" }, price, stock: stocks[3] },
]);

